import React from 'react';
import './News.css';

function News() {
  const news = [
    {
      id: 1,
      title: 'Cập Nhật: Thêm Phương Thức Thanh Toán Mới',
      date: '15/01/2025',
      content: 'Shop đã thêm hỗ trợ thanh toán qua VietQR, giúp bạn dễ dàng nạp tiền hơn.',
      category: '📢 Thông Báo'
    },
    {
      id: 2,
      title: 'Chương Trình Khuyến Mãi Tháng 1',
      date: '10/01/2025',
      content: 'Mua acc trên 200k được tặng 50k tiền thưởng. Hạn hót: Tết này!',
      category: '🎁 Khuyến Mãi'
    },
    {
      id: 3,
      title: 'Hướng Dẫn Bảo Vệ Tài Khoản',
      date: '05/01/2025',
      content: 'Cách cài đặt xác minh 2 lớp để bảo vệ tài khoản Roblox của bạn.',
      category: '📚 Hướng Dẫn'
    },
  ];

  return (
    <div className="news-container">
      <h1>📰 TIN TỨC</h1>
      <p className="subtitle">Cập nhật tin tức và thông báo mới nhất từ shop</p>

      <div className="news-grid">
        {news.map(article => (
          <div key={article.id} className="news-card">
            <div className="news-category">{article.category}</div>
            <h3>{article.title}</h3>
            <p className="news-date">📅 {article.date}</p>
            <p className="news-content">{article.content}</p>
            <a href="#" className="read-more">Đọc Thêm →</a>
          </div>
        ))}
      </div>
    </div>
  );
}

export default News;
